const essential=url=>/^\.\/manifest\.json(?:\?|$)/.test(url)||url==='./Readme.html'||url==='./'||url==='./index.html'||url==='./legal/index.html'||url==='./fuentes/index.html'||url==='./pruebas/index.html'||/\.(js|css)(?:\?|$)/.test(url);
